use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input on every call, before any step that could trap.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        // The one permitted fetch. A transport failure is a value, so it
        // yields zero characters rather than failing the node.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let notified = notifier::notify("heartbeat");
        if !notified {
            // The ensures clause requires notified == true, so a refused
            // notification must trap rather than emit a violating output.
            panic!("notifier refused the heartbeat; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
